contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters to attempt actions as if owner or not
    // Note: msg.sender for calls to c will be this contract; c was deployed with owner = deployer of C
    // so this contract is OWNER iff address(this) == c.owner(). We test both cases via a boolean param.
    function run(bool callAsOwner, address payable target, uint value, bytes calldata data) public payable {
        require(true);

        // record observables before the action
        uint beforeDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        // We will try to call one of the owner-only mutating functions depending on callAsOwner flag.
        // If callAsOwner is true but this contract is not the owner, we attempt nothing special —
        // the property will check that only owner can succeed.

        // Try withdraw (attempt to withdraw `value`)
        bool withdrewReverted;
        try c.withdraw{value: 0}(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try withdrawAll
        bool withdrewAllReverted;
        try c.withdrawAll{value: 0}() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Try sendMoney to target with data and value
        bool sendMoneyReverted;
        // ensure we have enough balance to send into c if we want to supply value to sendMoney call
        if (msg.value > 0) {
            require(address(this).balance >= msg.value);
            // forward Ether to c by calling fallback: use low-level call to send Ether to c so c.balance increases
            // But per constraints, every state-changing call on c must be a top-level statement. We perform
            // a deposit by calling c with value and empty data, which triggers fallback and increments depositsCount.
            (bool ok, ) = address(c).call{value: msg.value}("");
            // ignore ok; depositsCount increments on fallback regardless of sender
            ok; 
        }

        try c.sendMoney{value: 0}(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observables after
        uint afterDeposits = c.depositsCount();
        uint afterCBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // Determine whether this contract is owner according to public getter
        address owner = c.owner();
        bool amOwner = (owner == address(this));

        // General rule: If this contract is not owner, then all three owner-only calls must have reverted
        // and there must be no change to c.balance (except possible deposits we intentionally sent via msg.value) and depositsCount
        // If we intentionally sent msg.value into c before, that will have increased both c.balance and depositsCount; account for that.

        // compute expected change due to our optional initial deposit
        uint depositDelta = afterDeposits - beforeDeposits;
        uint balanceDelta = afterCBalance - beforeCBalance;

        assert(
            // If not owner: all owner-only calls revert
            (!amOwner && withdrewReverted && withdrewAllReverted && sendMoneyReverted &&
                // and aside from any explicit deposits we made (which must both increment depositsCount and balance by msg.value),
                // there should be no other balance or depositsCount changes. That means either we didn't send msg.value and no change,
                // or we did send msg.value and depositsCount increased by exactly 1 and balance increased by exactly msg.value.
                (
                    (msg.value == 0 && depositDelta == 0 && balanceDelta == 0) ||
                    (msg.value > 0 && depositDelta >= 1 && balanceDelta >= msg.value)
                )
            )
            ||
            // If am owner: at least one of the owner-only calls may succeed (we don't require which), but if any succeeded, c's balance or this contract's balance
            // must reflect the transfer (withdraw/withdrawAll/sendMoney might move Ether out of c). Conservatively require that if any did not revert,
            // then either c.balance decreased or this contract's balance increased (observed effect). If all reverted, that's also allowed.
            (amOwner && (
                ( !withdrewReverted || !withdrewAllReverted || !sendMoneyReverted) ?
                    (afterCBalance <= beforeCBalance || afterThis >= beforeThis) :
                    true
            ))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters
    function run(address payable target, uint value, bytes calldata data) public payable {
        require(true);

        // Record observables before any actions
        uint beforeDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        // Optionally send Ether into c to trigger fallback (which increments depositsCount)
        if (msg.value > 0) {
            require(address(this).balance >= msg.value);
            // Deposit Ether into c by calling it with value and empty data to trigger fallback
            (bool ok, ) = address(c).call{value: msg.value}("");
            ok; // ignore success boolean; fallback increments depositsCount on payable fallback
        }

        // Attempt owner-only operations and record whether they reverted
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observables after
        uint afterDeposits = c.depositsCount();
        uint afterCBalance = address(c).balance;
        uint afterThis = address(this).balance;

        address owner = c.owner();
        bool amOwner = (owner == address(this));

        uint depositDelta = afterDeposits - beforeDeposits;
        uint balanceDelta = afterCBalance - beforeCBalance;

        // General invariant:
        // - If not owner: all owner-only calls must revert, and apart from any explicit deposit we made (msg.value),
        //   there must be no other change to depositsCount or c.balance.
        // - If owner: if any owner-only call succeeded (did not revert), then either c.balance decreased or this contract's balance increased.
        assert(
            (
                !amOwner
                && withdrewReverted && withdrewAllReverted && sendMoneyReverted
                && (
                    // if we didn't deposit, no change; if we did, depositsCount increased by >=1 and balance increased by >= msg.value
                    (msg.value == 0 && depositDelta == 0 && balanceDelta == 0)
                    || (msg.value > 0 && depositDelta >= 1 && balanceDelta >= msg.value)
                )
            )
            ||
            (
                amOwner
                && (
                    // if any succeeded, require an observable transfer effect; if all reverted, allow it
                    ( (!withdrewReverted || !withdrewAllReverted || !sendMoneyReverted) ?
                        (afterCBalance <= beforeCBalance || afterThis >= beforeThis)
                        : true
                    )
                )
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function taking parameters. We take two deposit amounts and one withdraw amount
    // plus a target/data for sendMoney to exercise owner-only call. All Ether sent to C must come from
    // explicit parameters; do not read msg.value.
    function run(uint deposit1, uint deposit2, uint withdrawAmt, address payable target, bytes calldata data) public payable {
        require(address(this).balance >= deposit1 + deposit2);
        // Observables before any actions
        uint beforeDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;

        // First deposit: send Ether to c to trigger fallback (payable fallback increments depositsCount)
        if (deposit1 > 0) {
            (bool ok1, ) = address(c).call{value: deposit1}("");
            ok1; // ignore success boolean; fallback is payable and should accept
        }

        // Second deposit via a distinct external call
        if (deposit2 > 0) {
            (bool ok2, ) = address(c).call{value: deposit2}("");
            ok2;
        }

        // Attempt owner-only withdraw and sendMoney, capturing whether they revert
        bool withdrawReverted;
        try c.withdraw(withdrawAmt) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, withdrawAmt, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observables after
        uint afterDeposits = c.depositsCount();
        uint afterCBalance = address(c).balance;

        // Count how many deposit calls actually sent nonzero value
        uint depositCalls = 0;
        if (deposit1 > 0) depositCalls++;
        if (deposit2 > 0) depositCalls++;

        // General rule asserted:
        // 1) depositsCount increases by exactly depositCalls (each external nonzero-value call triggers fallback once)
        // 2) Owner-only actions (withdraw, withdrawAll, sendMoney): if any of them succeeded (did not revert), then C's balance cannot have increased compared to before the owner action attempts.
        //    This prevents owner-only functions from creating funds for the contract; they can only move funds out.
        // We express 2) by: if (any succeeded) then afterCBalance <= beforeCBalance + deposit1 + deposit2 - (deposit1 + deposit2) => afterCBalance <= beforeCBalance
        bool anyOwnerSucceeded = (!withdrawReverted) || (!withdrawAllReverted) || (!sendMoneyReverted);

        assert(
            (afterDeposits == beforeDeposits + depositCalls)
            && (!anyOwnerSucceeded || afterCBalance <= beforeCBalance)
        );
    }

    // allow receiving Ether (not strictly needed for this test, but present for completeness)
    receive() external payable { }
}

