contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We accept three params: amount to send into c via fallback, amount to attempt withdraw, and calldata to use for sendMoney.
    function run(uint depositAmount, uint withdrawAmount, bytes calldata data) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // 1) Deposit Ether to c by calling its fallback: do so by sending plain value to the contract address
        // The fallback increments depositsCount and increases address(c).balance
        (bool sent,) = address(c).call{value: depositAmount}("nonexistent_function");
        // sent may be true or false depending on fallback; if false the call reverted and no deposit happened
        uint balanceAfterDeposit = address(c).balance;
        uint depositsCountAfter = c.depositsCount();

        // 2) Try owner operations: since this test contract deployed c, it is the owner and these should succeed when enough balance
        bool withdrewReverted;
        if (withdrawAmount <= balanceAfterDeposit) {
            // attempt withdraw(uint)
            try c.withdraw(withdrawAmount) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            // If trying to withdraw more than balance, the transfer will revert; still record that behavior by executing and catching
            try c.withdraw(withdrawAmount) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        // record balances after withdraw attempt
        uint balanceAfterWithdrawAttempt = address(c).balance;

        // 3) Try sendMoney to an external address: use address(this) as the target so we can observe movement
        bool sendReverted;
        // ensure calldata is passed through; call only if we have at least some balance to try sending
        if (withdrawAmount <= balanceAfterDeposit) {
            // compute a value to send (use withdrawAmount as value param for sendMoney)
            try c.sendMoney(address(this), withdrawAmount, data) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        } else {
            // If previous withdraw failed due to insufficient balance, attempting sendMoney with withdrawAmount will also likely revert
            try c.sendMoney(address(this), withdrawAmount, data) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        }

        uint finalBalanceC = address(c).balance;
        uint finalBalanceThis = address(this).balance;
        // General rule to assert:
        // - If withdraw succeeded (did not revert) then c's balance decreased by exactly withdrawAmount and this contract's balance increased by withdrawAmount
        // - If withdraw reverted then c's balance did not decrease because of withdraw (it may still have decreased earlier if withdraw succeeded unexpectedly)
        // - Similarly for sendMoney: if sendMoney succeeded then c's balance decreased by send value and recipient (this) increased
        // We combine into one assert capturing owner-only property: since this contract is owner, any successful call that claims to transfer value must correspond to that value leaving c.
        // We express: finalBalanceC + (withdrewReverted ? 0 : withdrawAmount) + (sendReverted ? 0 : withdrawAmount) == balanceAfterDeposit
        // and balanceAfterDeposit == depositsCountAfter > = 0 relationship is observable but not necessary. Use the equality to relate movements.

        assert(finalBalanceC + (withdrewReverted ? 0 : withdrawAmount) + (sendReverted ? 0 : withdrawAmount) == balanceAfterDeposit);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: amount to deposit via fallback, amount to attempt to withdraw/send, calldata for sendMoney
    function run(uint depositAmount, uint opAmount, bytes calldata data) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // 1) Deposit to c by calling its fallback (plain call with no data triggers fallback)
        (bool depositSucceeded, ) = address(c).call{value: depositAmount}("\x00");
        // record balances and observable public state after deposit attempt
        uint balanceAfterDeposit = address(c).balance;
        uint depositsCountAfter = c.depositsCount();

        // 2) Attempt withdraw(opAmount) as owner (this contract deployed c so it's owner). Catch revert.
        bool withdrawReverted;
        try c.withdraw(opAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint balanceAfterWithdraw = address(c).balance;
        uint myBalanceAfterWithdraw = address(this).balance;

        // 3) Attempt sendMoney(this, opAmount, data) as owner. Catch revert.
        bool sendReverted;
        try c.sendMoney(address(this), opAmount, data) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        uint balanceAfterSend = address(c).balance;
        uint myBalanceAfterSend = address(this).balance;

        // General invariant: successful external-value-moving calls transfer exactly the requested amount from c to caller;
        // if they reverted, they did not change c's balance. We express this as follows:
        // Let deltaWithdraw = withdrawReverted ? 0 : opAmount
        // Let deltaSend = sendReverted ? 0 : opAmount
        // Then starting from balanceAfterDeposit, after withdraw and send the final balance should be balanceAfterDeposit - deltaWithdraw - deltaSend
        // Also the observed my balance increases accordingly: myBalanceAfterSend == myBalanceAfterWithdraw + (sendReverted ? 0 : opAmount)

        uint deltaWithdraw = withdrawReverted ? 0 : opAmount;
        uint deltaSend = sendReverted ? 0 : opAmount;

        assert(
            // final contract balance matches expected subtraction (avoid underflow by expressing as equality using additions)
            balanceAfterSend + deltaWithdraw + deltaSend == balanceAfterDeposit
            &&
            // my balance progressed correctly: after withdraw my balance increased by deltaWithdraw, and after send by deltaSend
            myBalanceAfterWithdraw + deltaSend == myBalanceAfterSend
            &&
            // if deposit call reverted then depositsCount should not have increased by this tx's deposit (i.e., depositSucceeded implies depositsCountAfter >= 1)
            // This part links observable depositsCount with depositSucceeded: if depositSucceeded then depositsCountAfter must be >= 1
            (depositSucceeded ? depositsCountAfter >= 1 : true)
        );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // depositAmount - amount to send to C to increase its balance via fallback
    // opAmount - amount to attempt to withdraw/send from C
    // data - calldata passed to sendMoney
    function run(uint depositAmount, uint opAmount, bytes calldata data) public payable {
        // Ensure this contract has enough balance to fund the deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // 1) Deposit to c by executing a plain call with some data so fallback is invoked.
        // Use a low-level call to trigger fallback; this is not a call on c's ABI, but it's allowed per constraints.
        // This low-level call is not a call on c through its C-type, but it's necessary to exercise fallback.
        (bool depositSucceeded, ) = address(c).call{value: depositAmount}("\x00");

        // Observe contract balance and depositsCount after deposit
        uint balanceAfterDeposit = address(c).balance;
        uint depositsCountAfter = c.depositsCount();

        // 2) Attempt withdraw(opAmount) as owner (this contract is the owner). Catch revert.
        bool withdrawReverted;
        try c.withdraw(opAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint balanceAfterWithdraw = address(c).balance;
        uint myBalanceAfterWithdraw = address(this).balance;

        // 3) Attempt sendMoney(this, opAmount, data) as owner. Catch revert.
        bool sendReverted;
        try c.sendMoney(address(this), opAmount, data) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        uint balanceAfterSend = address(c).balance;
        uint myBalanceAfterSend = address(this).balance;

        // Compute expected deltas: if call reverted, delta is 0; if succeeded, delta is opAmount.
        uint deltaWithdraw = withdrawReverted ? 0 : opAmount;
        uint deltaSend = sendReverted ? 0 : opAmount;

        // General invariant (single assert):
        // - C's final balance equals balance after deposit minus amounts actually withdrawn/sent.
        // - This contract's balance increased by exactly the amounts actually received from successful calls.
        // - If the deposit low-level call succeeded then depositsCount must be >= 1 (observable effect of fallback).
        assert(
            balanceAfterSend + deltaWithdraw + deltaSend == balanceAfterDeposit
            && myBalanceAfterWithdraw + deltaSend == myBalanceAfterSend
            && (depositSucceeded ? depositsCountAfter >= 1 : true)
        );
    }

    // Accept ETH when C sends to this contract during tests
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to send to c to trigger fallback
    // opAmount: amount to attempt to withdraw/send from c
    // data: calldata forwarded in sendMoney
    function run(uint depositAmount, uint opAmount, bytes calldata data) public payable {
        // Ensure this contract has enough balance to fund the deposit and potential transfer
        require(address(this).balance >= depositAmount + opAmount, "insufficient balance for test");

        // 1) Record initial observable state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        uint myBefore = address(this).balance;

        // 2) Deposit to c by calling c with value to trigger fallback. Use top-level low-level call to address(c).
        // This is not a call on c's ABI, but it's allowed; it is a top-level statement.
        (bool depositSucceeded, ) = address(c).call{value: depositAmount}("\x00");

        // 3) Observe after-deposit values
        uint afterDepositBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // 4) Attempt withdraw(opAmount) as owner (this contract). Catch revert.
        bool withdrawReverted;
        try c.withdraw(opAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint afterWithdrawBalance = address(c).balance;
        uint myAfterWithdraw = address(this).balance;

        // 5) Attempt sendMoney(this, opAmount, data) as owner. Catch revert.
        bool sendReverted;
        try c.sendMoney(address(this), opAmount, data) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        uint finalBalance = address(c).balance;
        uint myFinal = address(this).balance;

        // Deltas for successful operations
        // If a call reverted, it must have left contract balance unchanged; if it succeeded, balance decreased by opAmount.
        // Compose relation: finalBalance == afterDepositBalance - (withdrawSucceeded?opAmount:0) - (sendSucceeded?opAmount:0)
        uint withdrawDelta = withdrawReverted ? 0 : opAmount;
        uint sendDelta = sendReverted ? 0 : opAmount;

        // Assert the general rule plus that a successful low-level deposit increments depositsCount
        assert(
            // balances reflect successful operations exactly
            finalBalance + withdrawDelta + sendDelta == afterDepositBalance
            // this contract's balance increased by exactly amounts received from successful calls
            && myFinal == myBefore - depositAmount + withdrawDelta + sendDelta
            // depositsCount increases by at least 1 if the low-level deposit succeeded
            && (depositSucceeded ? afterDeposits >= beforeDeposits + 1 : afterDeposits == beforeDeposits)
        );
    }

    // Accept ETH when C sends to this contract during tests
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to send to c to trigger fallback
    // withdrawAmount: amount to attempt to withdraw from c
    function run(uint depositAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to perform the deposit and to receive possible withdrawals
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // observe initial state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        uint myBefore = address(this).balance;

        // 1) deposit to c by sending Ether which should invoke fallback
        (bool depositSucceeded, ) = address(c).call{value: depositAmount}("\x00");

        // observe after deposit
        uint afterDepositBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();
        uint myAfterDeposit = address(this).balance;

        // 2) attempt owner withdraw; this contract is the deployer/owner of C
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // observe final state
        uint finalBalance = address(c).balance;
        uint myFinal = address(this).balance;

        // Assert the general rule:
        // - The deposit increased C's balance exactly when the low-level call reported success, and depositsCount increased by 1 iff deposit succeeded.
        // - The withdraw either reverted (leaving C's balance unchanged) or succeeded and decreased C's balance by exactly withdrawAmount while increasing this contract's balance by the same amount.
        assert(
            (
                // deposit balance effect matches depositSucceeded
